"""Overdue fee statements: python3 fees.py INPUT_DIR OUTPUT_FILE (see /app/docs)."""
import csv
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


def cents(text):
    return int((Decimal(text.strip()) * 100).to_integral_value())


def parse_date(s):
    return date.fromisoformat(s.strip())


def read_csv(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        return list(csv.DictReader(f))


def read_policy(path):
    sections = {}
    cur = None
    with open(path, encoding="utf-8-sig") as f:
        for raw in f:
            line = raw.strip()
            if not line or line.startswith("#") or line.startswith(";"):
                continue
            if line.startswith("[") and line.endswith("]"):
                cur = line[1:-1].strip()
                sections[cur] = {}
                continue
            if "=" in line and cur is not None:
                k, v = line.split("=", 1)
                sections[cur][k.strip().lower()] = v.strip()
    return sections


def parse_offset(s):
    s = s.strip()
    sign = -1 if s[0] == "-" else 1
    s = s.lstrip("+-")
    h, m = s.split(":")[:2]
    return sign * (int(h) * 60 + int(m))


def patron_key(p):
    digits = re.sub(r"\D", "", p or "")
    return int(digits) if digits else None


def parse_instant(s):
    s = s.strip()
    m = re.match(r"^(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|z|[+-]\d\d:?\d\d)?$", s)
    y, mo, d, h, mi, sec, tz = m.groups()
    dt = datetime(int(y), int(mo), int(d), int(h), int(mi), int(sec or 0))
    if tz is None or tz in ("Z", "z"):
        off = 0
    else:
        off = parse_offset(tz if ":" in tz else tz[:3] + ":" + tz[3:])
    return dt - timedelta(minutes=off)  # naive UTC


def main(indir, outfile):
    pol = read_policy(os.path.join(indir, "policy.ini"))
    library = pol["statement"]["library"]
    pstart = parse_date(pol["statement"]["period_start"])
    pend = parse_date(pol["statement"]["period_end"])

    base_off = parse_offset(pol.get("clock", {}).get("offset", "+00:00"))
    changes = []
    for part in pol.get("clock", {}).get("changes", "").split(";"):
        part = part.strip()
        if not part:
            continue
        inst, off = part.split()
        changes.append((parse_instant(inst), parse_offset(off)))
    changes.sort()

    def local_from_utc(utc):
        off = base_off
        for inst, o in changes:
            if inst <= utc:
                off = o
        return utc + timedelta(minutes=off)

    items = {}
    for sec, vals in pol.items():
        if sec.lower().startswith("item:"):
            items[sec[5:].strip().lower()] = (sec[5:].strip(), {
                "loan_days": int(vals["loan_days"]), "renewals": int(vals["renewals"]),
                "grace": int(vals["grace_days"]), "daily": cents(vals["daily"]),
                "cap": cents(vals["loan_cap"])})
    cats = {}
    for sec, vals in pol.items():
        if sec.lower().startswith("category:"):
            sc = vals.get("statement_cap", "none").strip()
            cats[sec[9:].strip().lower()] = (sec[9:].strip(), {
                "cap": None if sc.lower() == "none" else cents(sc),
                "discount": int(vals.get("discount", "0") or 0),
                "exempt": {x.strip().lower() for x in vals.get("exempt", "").split(",") if x.strip()}})

    # branches and calendar
    branches = []
    open_days = {}
    for r in read_csv(os.path.join(indir, "branches.csv")):
        b = r["branch"].strip()
        branches.append(b)
        open_days[b] = {WEEKDAYS.index(x[:3].lower()) for x in r["open_days"].split()}
    cal = {}  # branch or '*' -> {date: status}
    for r in read_csv(os.path.join(indir, "calendar.csv")):
        ds = r["date"].strip()
        if ".." in ds:
            a, b = ds.split("..")
            first, last = parse_date(a), parse_date(b)
        else:
            first = last = parse_date(ds)
        tgt = cal.setdefault(r["branch"].strip(), {})
        st = r["status"].strip().lower()
        d = first
        while d <= last:
            tgt[d] = st
            d += timedelta(days=1)

    def is_open(branch, d):
        s = cal.get(branch, {}).get(d)
        if s is None:
            s = cal.get("*", {}).get(d)
        if s is not None:
            return s == "open"
        return d.weekday() in open_days.get(branch, set())

    def next_open(branch, d):
        for _ in range(4000):
            if is_open(branch, d):
                return d
            d += timedelta(days=1)
        return d

    # patrons
    patron_rows = {}
    for r in read_csv(os.path.join(indir, "patrons.csv")):
        k = patron_key(r["patron"])
        patron_rows.setdefault(k, []).append((parse_date(r["since"]), r["patron"].strip(), r["category"].strip()))
    for k in patron_rows:
        patron_rows[k].sort(key=lambda x: x[0])

    def category_on(k, d):
        best = None
        for since, name, cat in patron_rows.get(k, []):
            if since <= d:
                best = cat
        if best is None:
            best = patron_rows[k][0][2]
        return cats[best.lower()]

    # events
    events = {}
    expdir = os.path.join(indir, "exports")
    for name in sorted(os.listdir(expdir)):
        path = os.path.join(expdir, name)
        low = name.lower()
        if low.endswith(".csv"):
            for r in read_csv(path):
                r = {k: (v or "").strip() for k, v in r.items() if k is not None}
                eid = r.get("event", "")
                if not eid or eid in events:
                    continue
                r["_local"] = datetime.strptime(r["time"], "%Y-%m-%d %H:%M")
                events[eid] = r
        elif low.endswith(".jsonl"):
            with open(path, encoding="utf-8-sig") as f:
                for line in f:
                    line = line.strip().lstrip("\ufeff")
                    if not line:
                        continue
                    r = {k: (v.strip() if isinstance(v, str) else v) for k, v in json.loads(line).items()}
                    eid = r.get("event", "")
                    if not eid or eid in events:
                        continue
                    r["_local"] = local_from_utc(parse_instant(r["at"]))
                    events[eid] = r
    cancelled = set()
    for e in events.values():
        if e.get("type", "").lower() == "void" and e.get("target"):
            cancelled.add(e["target"])

    checkouts = {}
    others = {}
    for eid, e in events.items():
        if eid in cancelled:
            continue
        t = e.get("type", "").lower()
        if t == "checkout":
            checkouts[e["loan"]] = e
        elif t in ("renew", "return"):
            others.setdefault(e["loan"], []).append(e)

    one = timedelta(days=1)
    loans = []
    for lid, co in checkouts.items():
        cdate = co["_local"].date()
        if cdate > pend:
            continue
        tname, it = items[co["item_type"].lower()]
        br = co["branch"]
        due = next_open(br, cdate + timedelta(days=it["loan_days"]))
        nren = 0
        returned = None
        for e in sorted(others.get(lid, []), key=lambda x: (x["_local"], x.get("event", ""))):
            ld = e["_local"].date()
            if e["type"].lower() == "renew":
                if ld <= due and nren < it["renewals"] and ld <= pend:
                    nren += 1
                    due = next_open(br, ld + timedelta(days=it["loan_days"]))
            else:
                returned = ld - one if e.get("via", "").lower() == "dropbox" else ld
                break
        if returned is not None and returned < pstart:
            continue
        if returned is not None and returned > pend:
            returned_out = None
            end = pend
        else:
            returned_out = returned
            end = returned if returned is not None else pend
        od = 0
        d = due + one
        while d <= end:
            if is_open(br, d):
                od += 1
            d += one
        if od == 0:
            continue
        charged = od if od > it["grace"] else 0
        pk = patron_key(co["patron"])
        cname, cat = category_on(pk, cdate)
        base = charged * it["daily"]
        if it["daily"] is not None and it["item_type"] if False else False:
            pass
        if tname.lower() in cat["exempt"]:
            base = 0
        base = min(base, it["cap"])
        assessed = (base * (100 - cat["discount"]) + 50) // 100
        loans.append({"pk": pk, "loan": lid, "item": co.get("item", ""), "item_type": tname,
                      "branch": br, "checkout": cdate, "due": due, "returned": returned_out,
                      "overdue_days": od, "charged_days": charged, "assessed": assessed})

    # waivers
    waivers = []
    for r in read_csv(os.path.join(indir, "waivers.csv")):
        if r["status"].strip().lower() != "active":
            continue
        v = r["value"].strip()
        waivers.append((patron_key(r["patron"]), r["loan"].strip(),
                        None if v.lower() == "full" else cents(v)))

    by_patron = {}
    for l in loans:
        by_patron.setdefault(l["pk"], []).append(l)

    statements = []
    for pk in sorted(by_patron):
        ls = by_patron[pk]
        for l in ls:
            app = [w for w in waivers if w[0] == pk and w[1] in (l["loan"], "*")]
            if any(w[2] is None for w in app):
                l["waived"] = l["assessed"]
            else:
                l["waived"] = min(l["assessed"], sum(w[2] for w in app))
            l["net"] = l["assessed"] - l["waived"]
            l["capped"] = 0
        cname, cat = category_on(pk, pend)
        if cat["cap"] is not None:
            excess = sum(l["net"] for l in ls) - cat["cap"]
            if excess > 0:
                for l in sorted(ls, key=lambda x: (x["due"], x["loan"]), reverse=True):
                    take = min(excess, l["net"])
                    l["capped"] = take
                    excess -= take
                    if excess <= 0:
                        break
        for l in ls:
            l["billed"] = l["net"] - l["capped"]
        ls.sort(key=lambda x: (x["due"], x["loan"]))
        patron_name = patron_rows[pk][-1][1]
        st = {"patron": patron_name, "category": cname, "loans": []}
        for l in ls:
            st["loans"].append({
                "loan": l["loan"], "item": l["item"], "item_type": l["item_type"], "branch": l["branch"],
                "checkout": l["checkout"].isoformat(), "due": l["due"].isoformat(),
                "returned": l["returned"].isoformat() if l["returned"] else None,
                "overdue_days": l["overdue_days"], "charged_days": l["charged_days"],
                "assessed": l["assessed"], "waived": l["waived"], "capped": l["capped"],
                "billed": l["billed"]})
        for k in ("assessed", "waived", "capped", "billed"):
            st[k] = sum(x[k] for x in st["loans"])
        statements.append(st)

    summary = []
    for b in branches:
        row = {"branch": b, "loans": 0, "charged_days": 0, "assessed": 0, "waived": 0, "capped": 0, "billed": 0}
        for st in statements:
            for l in st["loans"]:
                if l["branch"] == b:
                    row["loans"] += 1
                    for k in ("charged_days", "assessed", "waived", "capped", "billed"):
                        row[k] += l[k]
        summary.append(row)

    out = {"library": library, "period": {"start": pstart.isoformat(), "end": pend.isoformat()},
           "statements": statements, "branches": summary}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
